import { Controller, Get, Delete } from '@nestjs/common';
@Controller('access')
export class AccessController {
  @Get() list() {}
  @Delete(':id') remove() {}
}

import { Controller, Post, Version } from '@nestjs/common';
@Controller({ path: 'users', version: '2' })
export class UsersController {
  @Post('login') login() {}
  @Version('3') @Post() create() {}
}

import { Controller, Get, Version, VERSION_NEUTRAL } from '@nestjs/common';
@Controller({ path: 'data', version: ['1', '2'] })
export class DataController {
  @Get('quotes') quotes() {}
  @Get('sitemap.xml') @Version(VERSION_NEUTRAL) sitemap() {}
}

import { Controller, Get } from '@nestjs/common';
const BASE = 'x';
@Controller(BASE)
export class DynamicController {
  @Get('a') a() {}
}

import { Controller, Get } from '@nestjs/common';
const base = { path: 'reports' };
@Controller({ ...base, version: '2' })
export class SpreadController {
  @Get('daily') daily() {}
}

import { Injectable, Get } from '@nestjs/common';
@Injectable()
export class NotAController {
  @Get() looksLikeARoute() {}
}

import { Module } from '@nestjs/common';
import { UserRepository } from '../user.repository';
import { UsersRelationalRepository } from './repositories/user.repository';
@Module({
  providers: [{ provide: UserRepository, useClass: UsersRelationalRepository }],
  exports: [UserRepository],
})
export class RelationalUserPersistenceModule {}

import { Module } from '@nestjs/common';
import { UsersService } from './users.service';
@Module({ providers: [UsersService] })
export class UsersModule {}

import { Module } from '@nestjs/common';
import { CacheStore } from './cache.store';
@Module({ providers: [{ provide: CacheStore, useFactory: () => new MemoryStore() }] })
export class CacheModule {}

import { Module } from '@nestjs/common';
@Module({ providers: [{ provide: 'CONFIG', useValue: { ttl: 5 } }] })
export class ConfigHolderModule {}

import { Module } from '@nestjs/common';
import { shared } from './shared';
@Module({ providers: [...shared, { ...base }] })
export class SpreadModule {}

import { Injectable } from '@nestjs/common';
@Injectable()
export class NotAModule {}
